import test from 'node:test';import assert from 'node:assert/strict';import {createServer} from 'node:http';import {readFile} from 'node:fs/promises';import {resolve,extname} from 'node:path';import {spawn} from 'node:child_process';import {fixture} from './fixture.mjs';
const root=resolve('.'),mime={'.html':'text/html','.mjs':'text/javascript','.json':'application/json','.css':'text/css'};
async function browserCheck({path='/',script}){const data=fixture();const server=createServer(async(req,res)=>{try{const pathname=new URL(req.url,'http://127.0.0.1').pathname;if(pathname==='/website-data.json'){res.setHeader('content-type','application/json');res.end(JSON.stringify(data));return;}if(pathname==='/browser-check.mjs'){res.setHeader('content-type','text/javascript');res.end("const run=async()=>{for(let n=0;n<240&&document.body.dataset.state==='loading';n++)await new Promise(r=>setTimeout(r,25));try{"+script+";const p=document.createElement('pre');p.id='browser-result';p.textContent='BROWSER_PASS';document.body.append(p);}catch(e){const p=document.createElement('pre');p.id='browser-result';p.textContent='BROWSER_FAIL:'+e.message;document.body.append(p);}};run();");return;}const file=resolve(root,pathname==='/'?'index.html':'.'+pathname);let bytes=await readFile(file);if(extname(file)==='.html')bytes=Buffer.from(bytes.toString().replace('</body>','<script type="module" src="/browser-check.mjs"></script></body>'));res.setHeader('content-type',mime[extname(file)]||'application/octet-stream');res.end(bytes);}catch{res.statusCode=404;res.end();}});await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+server.address().port,child=spawn(process.env.CHROMIUM_PATH||'/usr/bin/chromium',['--headless','--no-sandbox','--disable-dev-shm-usage','--disable-gpu','--no-proxy-server','--remote-debugging-port=0',origin+path],{stdio:['ignore','ignore','pipe']});let socket;try{const endpoint=await new Promise((resolve,reject)=>{let stderr='';const timer=setTimeout(()=>reject(Error('launch timeout')),10000);child.stderr.on('data',d=>{stderr+=d.toString();const m=/DevTools listening on (ws:\/\/127\.0\.0\.1:\d+\/[^\s]+)/.exec(stderr);if(m){clearTimeout(timer);resolve(m[1]);}});});const debugOrigin=new URL(endpoint).origin.replace('ws:','http:');let page;for(let n=0;n<100;n++){const pages=await(await fetch(debugOrigin+'/json/list')).json();page=pages.find(p=>p.type==='page');if(page)break;await new Promise(r=>setTimeout(r,30));}socket=new WebSocket(page.webSocketDebuggerUrl);await new Promise((r,j)=>{socket.addEventListener('open',r,{once:true});socket.addEventListener('error',j,{once:true});});let id=0;const pending=new Map();socket.addEventListener('message',e=>{const x=JSON.parse(e.data),p=pending.get(x.id);if(p){pending.delete(x.id);p.resolve(x.result);}});const ev=expression=>new Promise(resolve=>{const n=++id;pending.set(n,{resolve});socket.send(JSON.stringify({id:n,method:'Runtime.evaluate',params:{expression,returnByValue:true}}));});let result='';for(let n=0;n<900&&!result;n++){const x=await ev("document.getElementById('browser-result')?.textContent||''");result=x.result?.value||'';await new Promise(r=>setTimeout(r,25));}assert.equal(result,'BROWSER_PASS',result||'timeout');}finally{socket?.close();child.kill('SIGKILL');server.closeAllConnections();await new Promise(r=>server.close(r));}}
test('homepage is block-driven and island browsing hands off to WhatsApp only',async()=>browserCheck({script:"if(!document.querySelector('.hero-block'))throw Error('hero block missing');document.querySelector('[data-select-island=AGATTI]').click();document.querySelector('[data-kind=PRODUCT]').click();const cards=document.querySelectorAll('.item-card');if(cards.length!==1||!cards[0].textContent.includes('Tuna pickle'))throw Error('product browse');const text=new URL(cards[0].querySelector('a[target]').href).searchParams.get('text');if(!text.includes('Product: Tuna pickle')||text.includes('NOODY_ITEM:'))throw Error('core coupling');"}));
test('extra custom page renders its own blocks and menu link',async()=>browserCheck({path:'/page.html?slug=about',script:"if(!document.getElementById('pageRoot').textContent.includes('Our island network'))throw Error('custom page');if(!document.getElementById('navlinks').textContent.includes('About'))throw Error('menu page');"}));
test('item pages keep rich details, reviews and WhatsApp enquiry',async()=>browserCheck({path:'/item.html?kind=PRODUCT&id=22222222-2222-4222-8222-222222222222&island=AGATTI',script:"const text=document.getElementById('app').textContent;if(!text.includes('Weight')||!text.includes('250 g')||!text.includes('Good product.'))throw Error('rich product');const wa=new URL(document.getElementById('itemEnquiry').href).searchParams.get('text');if(!wa.includes('Product: Tuna pickle'))throw Error('whatsapp');"}));
test('Studio Pro can create page and arbitrary block without Core API',async()=>browserCheck({path:'/studio-builder.html',script:"document.getElementById('addPage').click();if(document.getElementById('pageEditor').classList.contains('hidden'))throw Error('page editor');document.getElementById('newBlockType').value='gallery';document.getElementById('addBlock').click();const saved=JSON.parse(localStorage.getItem('noody.website.studio.pro.v2'));if(!saved.data.pages.some(p=>p.slug.startsWith('new-page')&&p.blocks.some(b=>b.type==='gallery')))throw Error('page block not saved');if(JSON.stringify(saved).includes('noody-ai-production.up.railway.app'))throw Error('core api dependency');"}));

test('home language selection persists across website pages',async()=>browserCheck({script:"const ml=document.querySelector('[data-language=ml]');if(!ml)throw Error('language buttons missing');ml.click();if(localStorage.getItem('noody-language')!=='ml')throw Error('language not remembered');if(!ml.classList.contains('active'))throw Error('language button not active');"}));
test('Studio has explicit save checkpoint controls',async()=>browserCheck({path:'/studio-builder.html',script:"if(!document.getElementById('saveTop')||!document.getElementById('saveBottom')||!document.getElementById('savePage')||!document.getElementById('publishTop'))throw Error('save publish controls missing');document.getElementById('saveTop').click();const saved=JSON.parse(localStorage.getItem('noody.website.studio.pro.v2'));if(!saved?.data?.pages?.length)throw Error('explicit save failed');"}));
